const e = $json.execution || {}, w = $json.workflow || {};
const msg = (e.error && (e.error.message || e.error.description)) || 'وقع من غير رسالة';
return [{ json: { workflow: w.name || '', workflow_id: String(w.id || ''), node: e.lastNodeExecuted || (e.error && e.error.node && e.error.node.name) || '', message: String(msg).slice(0, 500), execution_id: String(e.id || ''), mode: e.mode || '', at: DateTime.now().setZone('Africa/Cairo').toFormat('yyyy-MM-dd HH:mm') } }];

// موظف التستنج: بيلف على السيستم كله ويكتب تقرير. أي حاجة حمرا بتتبعتلك على الواتساب كمان
const now = DateTime.now().setZone('Africa/Cairo');
const today = now.toFormat('yyyy-MM-dd'), wd = now.weekday; // 5 = الجمعة
const res = []; // [ok, name, detail]
const req = async (o) => { const t = Date.now(); try { const r = await this.helpers.httpRequest({ timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true, ...o }); return { s: r.statusCode, ms: Date.now() - t }; } catch (e) { return { s: 0, ms: Date.now() - t, e: String(e.message || e).slice(0, 120) }; } };
// 1) المواقع
const PAGES = [['الموقع الرئيسي', 'https://jaguarsmart.com/'], ['التطبيق /app', 'https://jaguarsmart.com/app/'], ['CRM جاجوار', 'https://jaguarsmart.com/crm/'], ['متجر الخامات', 'https://jaguarsmart.com/materials/'], ['Tuya Suez', 'https://jaguarsmart.com/tuya-suez/'], ['شاهي', 'https://jaguarsmart.com/shahi/'], ['منيو شاهي', 'https://jaguarsmart.com/shahi/menu/'], ['Nile Digital', 'https://jaguarsmart.com/nile-digital-solution/'], ['Cobra Egypt', 'https://jaguarsmart.com/cobra-egypt/'], ['AIX', 'https://aixegypt.com/']];
for (const [n, u] of PAGES) { const r = await req({ method: 'GET', url: u }); res.push([r.s >= 200 && r.s < 400, 'موقع: ' + n, r.s ? r.s + ' · ' + r.ms + 'ms' : 'مش بيفتح ' + (r.e || '')]); }
// 2) الـ webhooks اللي التطبيق والمواقع بتكلمها (من غير توكن لازم ترفض بأدب، مش تقع)
for (const h of ['all-inbox', 'shahi-team', 'nile-team', 'app-ops']) {
  const r = await req({ method: 'POST', url: 'https://jaguarsmart.com/api/hook/' + h, body: 'action=ping', headers: { 'content-type': 'application/x-www-form-urlencoded' } });
  res.push([r.s > 0 && r.s < 500, 'API: ' + h, r.s ? String(r.s) : 'مفيش رد ' + (r.e || '')]);
}
// 3) قواعد البيانات
const sb = await req({ method: 'GET', url: 'https://snrsfpprlynixotjipmo.supabase.co/auth/v1/health', headers: { apikey: 'sb_publishable_Q9zcnd6bo1cM4VDRysyjbA_XBr6lhds' } });
res.push([sb.s === 200, 'Supabase جاجوار', String(sb.s || sb.e)]);
const aix = await req({ method: 'GET', url: 'https://xenrnhgxwhujyvtpwmsk.supabase.co/auth/v1/health', headers: { apikey: 'sb_publishable_PWiz7ybQJDngH5Ox3vkx6g_GuCQnQ1R' } });
res.push([aix.s === 200, 'Supabase AIX', String(aix.s || aix.e)]);
// 4) مفتاح Gemini (الموظفين كلهم عليه)
const gm = $('اختبر مفتاح Gemini').first().json;
res.push([!!(gm && gm.models && gm.models.length), 'مفتاح Gemini', gm && gm.models ? 'شغال' : 'مش شغال: ' + JSON.stringify(gm && (gm.error || gm)).slice(0, 120)]);
// 5) الموظفين اشتغلوا النهارده؟
const ops = $('آخر العمليات').all().map(i => i.json).filter(r => r && r.id);
const has = (agent, d) => ops.some(r => r.agent === agent && r.day === d);
const yday = now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
res.push([has('content', today), 'كاتب المحتوى (بوست النهارده)', has('content', today) ? 'نزل' : 'مانزلش النهارده']);
if (wd !== 5) res.push([has('leads', today), 'صياد العملاء', has('leads', today) ? 'اشتغل' : 'مااشتغلش النهارده']);
res.push([has('summary', yday) || ops.length < 3, 'ملخص امبارح بالليل', has('summary', yday) ? 'اتكتب' : 'ماتكتبش']);
// 6) الأخطاء في آخر 24 ساعة
const since = Date.now() - 86400000;
const errs = $('الأخطاء المتسجلة').all().map(i => i.json).filter(r => r && r.id && new Date(r.createdAt).getTime() >= since);
const byWf = {}; errs.forEach(r => { const k = r.workflow || '?'; (byWf[k] = byWf[k] || []).push(r); });
const errLines = Object.entries(byWf).map(([k, v]) => '• ' + k + ': ' + v.length + ' مرة — آخرها في "' + (v[0].node || '?') + '": ' + String(v[0].message).slice(0, 120));
res.push([!errs.length, 'أخطاء آخر 24 ساعة', errs.length ? errs.length + ' خطأ في ' + Object.keys(byWf).length + ' workflow' : 'مفيش']);
const bad = res.filter(r => !r[0]);
let body = (bad.length ? '🔴 فيه ' + bad.length + ' مشكلة' : '🟢 كله شغال') + ' — فحصت ' + res.length + ' حاجة\n\n';
body += res.map(r => (r[0] ? '✅ ' : '❌ ') + r[1] + ' — ' + r[2]).join('\n');
if (errLines.length) body += '\n\nالأخطاء:\n' + errLines.join('\n');
const alert = '*موظف التستنج — ' + today + '*\n' + (bad.length ? '🔴 فيه ' + bad.length + ' مشكلة:\n' + bad.map(r => '❌ ' + r[1] + ' — ' + r[2]).join('\n') + (errLines.length ? '\n\n' + errLines.slice(0, 6).join('\n') : '') + '\n\nالتفاصيل في شاشة العمليات في التطبيق.' : '');
return [{ json: { kind: 'report', business: 'all', agent: 'tester', title: (bad.length ? '🔴 ' : '🟢 ') + 'فحص السيستم — ' + today, body, link: '', status: 'done', review: bad.length ? 'محتاج تدخل' : '', ref_table: 'system_errors', ref_id: '', decided_at: '', day: today, problems: bad.length, alert } }];
